fn getImmediateShift(state: u16, sym: u16) ?i16 {
    for (xExcludes[xExcludeStart[state]..xExcludeStart[state + 1]]) |x| {
        if (x.sym == sym) return @intCast(x.shift);
    }
    return null;
}

fn startState(start: Start) u16 {
    return switch (start) {
        .@"routine" => 0,
        .@"commands" => 1,
        .@"expr" => 2,
        .@"doarg" => 3,
        .@"gotoarg" => 4,
    };
}

